rules:
.quick-date {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    min-width: 0;
    width: min(100%, var(--control-size));
    justify-self: center;
    padding: 0;
    border: 0;
    border-radius: var(--radius-control);
    background: var(--color-transparent);
    color: var(--text-primary);
    font-size: max(var(--text-min), var(--text-body));
    font-weight: 500;
    transition: background var(--duration-fast), color var(--duration-fast);
}
